import{_ as u,C as o,o as d,c as g,j as t,a,E as s,a8 as b}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/LnQce-eHm8k-640.webp",v="/schedule-dashboard/thumbs/yt/LnQce-eHm8k-1280.webp",n="/schedule-dashboard/thumbs/yt/1_lX0m64-aI-640.webp",f="/schedule-dashboard/thumbs/yt/1_lX0m64-aI-1280.webp",i="/schedule-dashboard/thumbs/yt/CvmZtAPmAW4-640.webp",y="/schedule-dashboard/thumbs/yt/CvmZtAPmAW4-1280.webp",l="/schedule-dashboard/thumbs/yt/9-Y_oS9OBLc-640.webp",k="/schedule-dashboard/thumbs/yt/9-Y_oS9OBLc-1280.webp",h="/schedule-dashboard/thumbs/yt/3osCbSufv8g-640.webp",_="/schedule-dashboard/thumbs/yt/3osCbSufv8g-1280.webp",c="/schedule-dashboard/thumbs/yt/jNFv1Lr2Db4-640.webp",A="/schedule-dashboard/thumbs/yt/jNFv1Lr2Db4-1280.webp",w="/schedule-dashboard/thumbs/yt/mNo24Omj8X4-640.webp",S="/schedule-dashboard/thumbs/yt/mNo24Omj8X4-1280.webp",Q=JSON.parse('{"title":"AI Digest · Sun 01 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-01","routine":"digest"},"relativePath":"digest/2026-11-01.md","filePath":"digest/[date].md"}'),I={name:"digest/2026-11-01.md"},L=r+" 640w, "+v+" 1280w",C=n+" 640w, "+f+" 1280w",O=i+" 640w, "+y+" 1280w",P=l+" 640w, "+k+" 1280w",B=h+" 640w, "+_+" 1280w",N=c+" 640w, "+A+" 1280w",x=w+" 640w, "+S+" 1280w",T={id:"ai-digest-·-sun-01-nov-2026",tabindex:"-1"};function W(j,e,D,M,X,H){const p=o("Badge"),m=o("DayFilter");return d(),g("div",null,[t("h1",T,[e[0]||(e[0]=a("AI Digest · Sun 01 Nov 2026 ",-1)),s(p,{type:"tip",text:"7"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-sun-01-nov-2026","aria-label":'Permalink to "AI Digest · Sun 01 Nov 2026 <Badge type="tip" text="7" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 1 Nov 2026 · run date Sun 01 Nov 2026 · 7 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(` 5 new talks in the last 24 hours, all with full transcripts. The freshest is Oracle's Jeff Smith on locking down agent access to databases (1 Nov, 4:30 AM IST), worth watching for exposing vetted reports as tools instead of letting agents write SQL. The other picks are Bumble's five lessons from A/B testing an AI feature (78% wanted it, 10–15% used it) and imec's hard numbers on when self-hosting coding agents beats APIs. Oracle's second talk, Richmond Alake's "intelligence plane", is mostly a repeat of agent-memory ground, and the Upstart/Coval voice-agent evals talk is familiar apart from its 33%-to-92% judge-agreement story.`)]),t("p",null,[t("strong",null,"Better Stack:"),a(" 2 new videos. The freshest is a JetKVM remote power-button hardware build (31 Oct, 11:35 PM IST, no AI content); the more useful one is a review of Worktrunk, a Git worktree tool for running several coding agents in parallel.")])],-1)),s(m),e[5]||(e[5]=b('<div class="grid cards2"><article class="it full" id="v-LnQce-eHm8k" data-title="Your AI Agent Wants Your Data. Here&#39;s How to Lock It Down - Jeff Smith, Oracle" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=LnQce-eHm8k" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+L+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=LnQce-eHm8k" target="_blank" rel="noopener">Your AI Agent Wants Your Data. Here&#39;s How to Lock It Down - Jeff Smith, Oracle</a></h3><div class="meta">AI Engineer · Jeff Smith, Oracle · uploaded 1 Nov, 4:30 AM IST · 21:40</div><div class="verdict v-worth"><b>Verdict:</b> worth watching from <a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=493s" target="_blank" rel="noopener">8:13</a> for the reports-as-tools pattern; skip the swag banter at the start.</div><div class="repeat">🔁 Repeat: &#39;MCP servers&#39; — seen 36 times before. New here: Oracle&#39;s database MCP server exposing your team&#39;s vetted reports as two tools instead of letting the agent write SQL.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 27 times before. New here: &quot;deep data security&quot;, where the database strips rows from results based on the user&#39;s SSO roles.</div><div class="sh">Why natural language to SQL is risky</div><ul><li><strong>One SQL interface for everything (repeat):</strong> Oracle now stores vectors, graph and other data types next to relational tables, so one MCP server into the database covers RAG over all of it without copying data to eight or nine platforms (<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=93s" target="_blank" rel="noopener">1:33</a>–<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=250s" target="_blank" rel="noopener">4:10</a>)</li><li><strong>&quot;If it compiles, ship it&quot;:</strong> LLM-written queries often run cleanly and still return the wrong data, and agents brute-force the data dictionary to find things, burning tokens and time (<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=433s" target="_blank" rel="noopener">7:13</a>–<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=493s" target="_blank" rel="noopener">8:13</a>)</li></ul><div class="sh">Use case 1: reports as tools</div><ul><li><strong>Vetted reports instead of ad hoc SQL:</strong> Load the team&#39;s existing reports into the MCP server, each with a description, sample questions and parameters; the agent can pick the wrong report but can&#39;t write wrong SQL. 500 reports appear as just two tools, list reports and execute report, so context isn&#39;t blown out (<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=493s" target="_blank" rel="noopener">8:13</a>–<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=615s" target="_blank" rel="noopener">10:15</a>)</li><li><strong>Teaching the data model:</strong> Ad hoc SQL can be switched off entirely, and with the right OAuth scope the tool can show the agent the SQL behind a report so it learns how the data is laid out and one-shots later queries (<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=615s" target="_blank" rel="noopener">10:15</a>–<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=676s" target="_blank" rel="noopener">11:16</a>)</li></ul><div class="sh">Use cases 2 and 3: tuning and schema docs</div><ul><li><strong>Performance tuning on a read-only standby:</strong> Point the agent at a Data Guard read-only standby rather than production, and give it a few multi-action tools (for example, generate an AWR performance report or collect optimizer statistics) instead of 15 single-use tools; it advises, a human acts (<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=706s" target="_blank" rel="noopener">11:46</a>–<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=889s" target="_blank" rel="noopener">14:49</a>)</li><li><strong>Schema annotations:</strong> A schema-info tool returns a compressed JSON dictionary (verbose, medium or slim, with keyword filters) instead of the agent querying every table, and a generate-annotations tool reads your Confluence pages, PDFs and spreadsheets to annotate tables, shown on his Strava workout data (<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=889s" target="_blank" rel="noopener">14:49</a>–<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=1162s" target="_blank" rel="noopener">19:22</a>)</li></ul><div class="sh">Security and roadmap</div><ul><li><strong>Deep data security:</strong> Agents connect through the user&#39;s SSO (for example Azure AD), and the database strips rows the user isn&#39;t allowed to see from results before they reach the agent, so an HR manager&#39;s agent sees salaries and others&#39; don&#39;t. Put security in the database, not just the tools (<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=767s" target="_blank" rel="noopener">12:47</a>–<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=828s" target="_blank" rel="noopener">13:48</a>) (<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=1162s" target="_blank" rel="noopener">19:22</a>–<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=1252s" target="_blank" rel="noopener">20:52</a>)</li><li><strong>Coming next:</strong> MCP apps putting a database GUI inside your agent later this year, skills delivered via tools, and automated RAG pipelines; details at oracle.com/mcp (<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=1252s" target="_blank" rel="noopener">20:52</a>–<a href="https://www.youtube.com/watch?v=LnQce-eHm8k&amp;t=1300s" target="_blank" rel="noopener">21:40</a>)</li></ul></div></article><article class="it full" id="v-1_lX0m64-aI" data-title="Everyone Has the Same AI Models. Here&#39;s What Sets Agents Apart - Richmond Alake, Oracle" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=1_lX0m64-aI" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+C+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=1_lX0m64-aI" target="_blank" rel="noopener">Everyone Has the Same AI Models. Here&#39;s What Sets Agents Apart - Richmond Alake, Oracle</a></h3><div class="meta">AI Engineer · Richmond Alake, Oracle · uploaded 1 Nov, 12:30 AM IST · 25:47</div><div class="verdict v-skim"><b>Verdict:</b> skim from <a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=832s" target="_blank" rel="noopener">13:52</a> for the demo numbers and memory-routing idea; much of the rest is Oracle product tour.</div><div class="repeat">🔁 Repeat: &#39;agent memory&#39; — seen 16 times before (this is Oracle&#39;s second memory talk in two days). New here: framing it as an &quot;intelligence plane&quot; above the control plane, and a fine-tuned small model that routes memories to the right store.</div><div class="repeat">🔁 Repeat: &#39;decision models&#39; — seen 5 times before.</div><div class="repeat">🔁 Repeat: &#39;software factory&#39; — seen 14 times before, only briefly mentioned here.</div><div class="sh">From control plane to intelligence plane</div><ul><li><strong>Memory basics (repeat):</strong> Memory is how an agent retains, reuses, recalls and refines information (his &quot;four Rs&quot;), split into short- and long-term and into semantic, episodic, procedural and working memory (<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=31s" target="_blank" rel="noopener">0:31</a>–<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=91s" target="_blank" rel="noopener">1:31</a>)</li><li><strong>Control plane versus intelligence plane:</strong> The control plane governs identity, policy, orchestration and auditing; the intelligence plane covers what the agent knows (knowledge), remembers (memory), may see (governance) and how it improves (continual learning) (<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=91s" target="_blank" rel="noopener">1:31</a>–<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=153s" target="_blank" rel="noopener">2:33</a>) (<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=495s" target="_blank" rel="noopener">8:15</a>–<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=525s" target="_blank" rel="noopener">8:45</a>)</li><li><strong>&quot;AF is Midway&quot;:</strong> In WWII, the small Pearl Harbor codebreaking team, which kept months of intercepts on paper, worked out that &quot;AF&quot; meant Midway while Washington, with the same data, read it differently. His point: everyone has the same models, and information isn&#39;t intelligence (<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=277s" target="_blank" rel="noopener">4:37</a>–<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=463s" target="_blank" rel="noopener">7:43</a>)</li></ul><div class="sh">Demo: governed versus naive agent</div><ul><li><strong>Fewer tokens, more accuracy:</strong> A finance analyst agent built with an ontology and semantic layer gets answers right 99% of the time using about 32K tokens, versus about 200K for a naive agent; the naive one gets &quot;concentration&quot; and &quot;counterparty&quot; questions wrong (<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=832s" target="_blank" rel="noopener">13:52</a>–<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=1018s" target="_blank" rel="noopener">16:58</a>)</li><li><strong>What to do now:</strong> Treat memory as data, write down your entities and definitions, push entitlements into the data layer and capture memory traces, since those become your fine-tuning data (<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=1018s" target="_blank" rel="noopener">16:58</a>–<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=1111s" target="_blank" rel="noopener">18:31</a>)</li></ul><div class="sh">Oracle&#39;s pieces</div><ul><li><strong>Product tour (mostly repeat):</strong> An agent memory Python package that generates context cards, deep data security so the agent inherits the user&#39;s row access, a private AI services container for on-prem embeddings, LLMs and rerankers, and a no-code Private Agent Factory (<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=1080s" target="_blank" rel="noopener">18:00</a>–<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=1234s" target="_blank" rel="noopener">20:34</a>) (<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=1390s" target="_blank" rel="noopener">23:10</a>–<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=1452s" target="_blank" rel="noopener">24:12</a>)</li><li><strong>Fine-tuned memory routing:</strong> In his open-source memory tool, a small open model fine-tuned on his own labelled conversations decides whether each item goes to conversation or workflow memory, replacing hand-written routing code; embeddings and rerankers are the other easy targets for fine-tuning (<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=1252s" target="_blank" rel="noopener">20:52</a>–<a href="https://www.youtube.com/watch?v=1_lX0m64-aI&amp;t=1390s" target="_blank" rel="noopener">23:10</a>)</li></ul></div></article><article class="it full" id="v-CvmZtAPmAW4" data-title="78% Wanted This AI Feature. Almost Nobody Used It - Supriya Subudhi, Bumble" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=CvmZtAPmAW4" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+O+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=CvmZtAPmAW4" target="_blank" rel="noopener">78% Wanted This AI Feature. Almost Nobody Used It - Supriya Subudhi, Bumble</a></h3><div class="meta">AI Engineer · Supriya Subudhi, Bumble · uploaded 31 Oct, 2:30 PM IST · 14:44</div><div class="verdict v-worth"><b>Verdict:</b> worth watching; short, concrete and a fresh product-manager angle.</div><div class="repeat">🔁 Repeat: &#39;token costs / AI spend&#39; — seen 14 times before. New here: the product side, with A/B test numbers from a consumer app rather than an engineering team&#39;s bill.</div><div class="sh">The feature</div><ul><li><strong>AI photo feedback:</strong> Bumble (over 20 million monthly users) gave AI-generated tips on how to improve dating-profile photos, based on what the team knows works (<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=91s" target="_blank" rel="noopener">1:31</a>–<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=182s" target="_blank" rel="noopener">3:02</a>)</li></ul><div class="sh">Five lessons from the A/B test</div><ul><li><strong>Users ask for it, then ignore it:</strong> 78% of surveyed users said they wanted profile feedback, but only 10–15% used it in the 50/50 test. Adoption rose once the prompt appeared inside existing flows, such as when adding photos or when someone wasn&#39;t getting matches (<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=182s" target="_blank" rel="noopener">3:02</a>–<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=303s" target="_blank" rel="noopener">5:03</a>)</li><li><strong>The average hides the tail:</strong> Top-line results were good (more photos added, more profile edits), but the AI told already-smiling people to smile more. They added guardrails (never comment on things people can&#39;t change, like skin colour or height) and evals that read real outputs per segment, gender and language (<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=303s" target="_blank" rel="noopener">5:03</a>–<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=474s" target="_blank" rel="noopener">7:54</a>)</li><li><strong>Green dashboard, red bill:</strong> The best model was about 10x the cost of a simpler approach, before eval costs; unlike classic ML, GenAI cost grows with every use. Know whether you&#39;re chasing short-term revenue or long-term brand value before choosing a budget (<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=474s" target="_blank" rel="noopener">7:54</a>–<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=637s" target="_blank" rel="noopener">10:37</a>)</li><li><strong>The win came from the model:</strong> Switching to a cheaper model also shrank the results, showing the lift came from the model rather than the idea of feedback; fast eval loops over models and prompts eventually found a cheap option that still worked (<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=637s" target="_blank" rel="noopener">10:37</a>–<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=709s" target="_blank" rel="noopener">11:49</a>)</li><li><strong>No global rollout:</strong> Regulation kept the feature US-only (she compares Meta&#39;s Muse AI, only in the US and Canada), so compliance has to be considered at the start (<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=709s" target="_blank" rel="noopener">11:49</a>–<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=834s" target="_blank" rel="noopener">13:54</a>)</li><li><strong>Five questions to ask:</strong> Are people using it or just saying they will? Do you read real outputs? Does it pay off after all costs? Can you afford a win on the best model? Which markets can you legally ship in? (<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=834s" target="_blank" rel="noopener">13:54</a>–<a href="https://www.youtube.com/watch?v=CvmZtAPmAW4&amp;t=884s" target="_blank" rel="noopener">14:44</a>)</li></ul></div></article><article class="it full" id="v-9-Y_oS9OBLc" data-title="When Running Your Own AI Models Beats Paying for APIs - Steven Latré, imec" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=9-Y_oS9OBLc" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+P+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc" target="_blank" rel="noopener">When Running Your Own AI Models Beats Paying for APIs - Steven Latré, imec</a></h3><div class="meta">AI Engineer · Steven Latré, imec · uploaded 31 Oct, 1:30 PM IST · 18:30</div><div class="verdict v-worth"><b>Verdict:</b> worth watching from <a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=448s" target="_blank" rel="noopener">7:28</a> if you weigh self-hosting; model names come from auto-captions.</div><div class="repeat">🔁 Repeat: &#39;open source / local models&#39; — seen 47 times before, and &#39;inference / serving&#39; 36 times. New here: hard break-even numbers for self-hosting coding agents, including concurrency and harness effects (Revolut&#39;s self-hosting talk on 30 Oct covered similar ground from the user side).</div><div class="sh">The study</div><ul><li><strong>Who and why:</strong> imec, the Belgian semiconductor R&amp;D lab, ran thousands of SWE-Bench Pro runs to measure what moving long-running coding agents from APIs to rented or owned GPUs really costs; owning the stack blows up the design space (model, harness, hardware, CPU-to-GPU balance, KV cache) (<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=12s" target="_blank" rel="noopener">0:12</a>–<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=328s" target="_blank" rel="noopener">5:28</a>)</li><li><strong>Setup:</strong> Three coding harnesses (Codex and Claude Code among them) across an API baseline and open-weight models of different sizes, each mapped to the smallest hardware that could serve it at scale (<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=328s" target="_blank" rel="noopener">5:28</a>–<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=448s" target="_blank" rel="noopener">7:28</a>)</li></ul><div class="sh">Findings</div><ul><li><strong>Accuracy tiers:</strong> Smaller open models like Qwen and DeepSeek resolved about 35–40% of tasks, GLM was around Opus level, and Kimi K3 hit 86% (he suspects some training-set overlap) (<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=448s" target="_blank" rel="noopener">7:28</a>–<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=520s" target="_blank" rel="noopener">8:40</a>)</li><li><strong>Cost moves in steps:</strong> Qwen and DeepSeek score about the same but DeepSeek needs roughly 4x the hardware; going from GLM to Kimi K3 adds about 20% accuracy for only about 15% more GPU rent (<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=520s" target="_blank" rel="noopener">8:40</a>–<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=608s" target="_blank" rel="noopener">10:08</a>)</li><li><strong>Concurrency matters more than accuracy:</strong> KV cache per user fills memory fast; even on big hardware, Kimi K3 served only about four concurrent users reliably and was still about 3x slower than the Claude Code API baseline (<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=608s" target="_blank" rel="noopener">10:08</a>–<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=757s" target="_blank" rel="noopener">12:37</a>)</li><li><strong>Break-even utilisation:</strong> On small systems you need about 89% GPU utilisation to beat APIs (unrealistic); on 8x B200 machines about 15% is enough. GLM-class workloads are the sweet spot, with about 24–25% total-cost savings for coding assistance (<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=757s" target="_blank" rel="noopener">12:37</a>–<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=871s" target="_blank" rel="noopener">14:31</a>)</li><li><strong>Harness choice halves the bill:</strong> All harnesses reached similar accuracy, but with GLM, Codex generated about half the tokens of the others, halving GPU wall time, which matters once you pay for the GPU (<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=871s" target="_blank" rel="noopener">14:31</a>–<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=980s" target="_blank" rel="noopener">16:20</a>)</li><li><strong>Next:</strong> A public benchmarking dataset and an alliance bringing software and chip/infrastructure companies together (<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=980s" target="_blank" rel="noopener">16:20</a>–<a href="https://www.youtube.com/watch?v=9-Y_oS9OBLc&amp;t=1110s" target="_blank" rel="noopener">18:30</a>)</li></ul></div></article><article class="it full" id="v-3osCbSufv8g" data-title="Voice AI Where One Wrong Question Breaks the Rules - Shiv Indap, Upstart &amp; Brooke Hopkins, Coval" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=3osCbSufv8g" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+B+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=3osCbSufv8g" target="_blank" rel="noopener">Voice AI Where One Wrong Question Breaks the Rules - Shiv Indap, Upstart &amp; Brooke Hopkins, Coval</a></h3><div class="meta">AI Engineer · Shiv Indap (Upstart) and Brooke Hopkins (Coval) · uploaded 31 Oct, 12:30 PM IST · 17:03</div><div class="verdict v-skim"><b>Verdict:</b> skim from <a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=423s" target="_blank" rel="noopener">7:03</a> for the judge-agreement story; the loop itself is familiar.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 49 times before; &#39;LLM-as-a-judge&#39; 10 times; &#39;human-in-the-loop review&#39; 26 times; &#39;voice agents&#39; 4 times (plus several earlier voice-agent talks). New here: a real lending use case and the climb from 33% to 92% judge–human agreement.</div><div class="sh">The use case</div><ul><li><strong>Loan verification calls:</strong> About 90% of Upstart applicants are decided instantly; the other 10% get a call asking three things: will income continue for three months, how will you use the funds, and any outstanding obligations like alimony or wage garnishments (<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=62s" target="_blank" rel="noopener">1:02</a>–<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=184s" target="_blank" rel="noopener">3:04</a>)</li><li><strong>Compliance traps:</strong> If someone says the money is for medical costs, the agent must not ask the amount; &quot;travel to a graduation&quot; needs a follow-up on whose graduation; and it must politely sidestep &quot;when do I get my money&quot; (<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=184s" target="_blank" rel="noopener">3:04</a>–<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=254s" target="_blank" rel="noopener">4:14</a>)</li></ul><div class="sh">Human review and judges</div><ul><li><strong>Outgrowing the spreadsheet:</strong> Every call was human-reviewed in a Google Sheet that grew from 5 to 15 ad hoc columns, so they moved to structured review queues in Coval (<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=254s" target="_blank" rel="noopener">4:14</a>–<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=328s" target="_blank" rel="noopener">5:28</a>)</li><li><strong>Metrics (repeat):</strong> An LLM judge scores each finished call on accuracy, clarity, completeness, policy alignment, correct escalation and CSAT; drop metrics that don&#39;t help (<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=328s" target="_blank" rel="noopener">5:28</a>–<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=423s" target="_blank" rel="noopener">7:03</a>)</li><li><strong>33% to 92%:</strong> At launch the compliance judge agreed with human reviewers only 33% of the time. Writing down tribal knowledge in the agent, resolving disagreements between human reviewers, and then improving the judge itself got it to 92% (<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=423s" target="_blank" rel="noopener">7:03</a>–<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=532s" target="_blank" rel="noopener">8:52</a>)</li></ul><div class="sh">The improvement loop</div><ul><li><strong>Monitor and route (mostly repeat):</strong> Score every live call, catch known failures plus unknown ones via clustering and anomaly detection, and route only flagged calls to the right team (agent, compliance or engineering) (<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=532s" target="_blank" rel="noopener">8:52</a>–<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=751s" target="_blank" rel="noopener">12:31</a>)</li><li><strong>Re-simulate before shipping:</strong> Fixes are tested with voice-to-voice simulations (accents, background noise, interruptions) before production, then &quot;self-healing&quot; agents propose fixes, but every change sits behind a feature flag and is signed off by engineers or compliance (<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=751s" target="_blank" rel="noopener">12:31</a>–<a href="https://www.youtube.com/watch?v=3osCbSufv8g&amp;t=1023s" target="_blank" rel="noopener">17:03</a>)</li></ul></div></article><article class="it full" id="v-jNFv1Lr2Db4" data-title="I Hacked My PC&#39;s Power Button So I Can Turn It On From Anywhere (JetKVM + ATX)" data-channel="Better Stack" data-verdict="skip"><a class="th" href="https://www.youtube.com/watch?v=jNFv1Lr2Db4" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+N+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-skip">skip</span><h3><a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4" target="_blank" rel="noopener">I Hacked My PC&#39;s Power Button So I Can Turn It On From Anywhere (JetKVM + ATX)</a></h3><div class="meta">Better Stack · Andress · uploaded 31 Oct, 11:35 PM IST · 10:07</div><div class="verdict v-skip"><b>Verdict:</b> skip unless you want remote power-on for a home workstation; no AI content.</div><p class="note">No repeats: a hardware how-to, unlike anything in history.</p><div class="sh">What JetKVM is</div><ul><li><strong>KVM over IP:</strong> A deck-of-cards-sized open-source box that captures the PC&#39;s HDMI output at up to 1080p/60 fps, acts as keyboard and mouse over USB-C, and streams to your browser over WebRTC with about 30–60 ms latency; because it works at hardware level you can get into the BIOS (<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=35s" target="_blank" rel="noopener">0:35</a>–<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=158s" target="_blank" rel="noopener">2:38</a>)</li><li><strong>The ATX Extension Board:</strong> JetKVM can&#39;t press a power button on its own; the add-on board wires to the motherboard&#39;s power-button pins and reads the power LED so the web UI knows if the PC is on (<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=158s" target="_blank" rel="noopener">2:38</a>–<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=188s" target="_blank" rel="noopener">3:08</a>)</li></ul><div class="sh">Wiring it</div><ul><li><strong>Front panel header:</strong> On his Gigabyte Z890 board the header is labelled F_PANEL; the ribbon cable splits into power, reset, power-LED and HDD-LED wires. His board&#39;s layout differed from JetKVM&#39;s assumed standard, so he went pin by pin with the manual (<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=188s" target="_blank" rel="noopener">3:08</a>–<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=252s" target="_blank" rel="noopener">4:12</a>)</li><li><strong>Keeping the case button:</strong> The ATX board has a second row of pins, so he used Dupont jumpers to keep the case&#39;s power button working; the board mounts on a spare PCIe bracket without using a slot (<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=252s" target="_blank" rel="noopener">4:12</a>–<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=326s" target="_blank" rel="noopener">5:26</a>)</li><li><strong>Power it from the wall:</strong> Four cables (Ethernet, HDMI, USB-C to the PC, extension cable to the ATX board), but power must come from a wall charger, since the PC&#39;s USB ports are dead when it&#39;s off (<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=326s" target="_blank" rel="noopener">5:26</a>–<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=392s" target="_blank" rel="noopener">6:32</a>)</li></ul><div class="sh">Demo</div><ul><li><strong>Full loop:</strong> From a laptop browser he presses power, watches the motherboard logo and Windows login, then shuts down; with JetKVM&#39;s free cloud access at app.jetkvm.com he does the same from his phone (<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=392s" target="_blank" rel="noopener">6:32</a>–<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=524s" target="_blank" rel="noopener">8:44</a>)</li><li><strong>Tip:</strong> If the video sticks on &quot;Connecting&quot;, a VPN browser extension blocking WebRTC was the cause (<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=524s" target="_blank" rel="noopener">8:44</a>–<a href="https://www.youtube.com/watch?v=jNFv1Lr2Db4&amp;t=548s" target="_blank" rel="noopener">9:08</a>)</li></ul></div></article><article class="it full" id="v-mNo24Omj8X4" data-title="The Best Git Worktree Tool I&#39;ve Used (Worktrunk)" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=mNo24Omj8X4" target="_blank" rel="noopener"><img src="'+w+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=mNo24Omj8X4" target="_blank" rel="noopener">The Best Git Worktree Tool I&#39;ve Used (Worktrunk)</a></h3><div class="meta">Better Stack · Josh · uploaded 31 Oct, 1:45 PM IST · 7:14</div><div class="verdict v-worth"><b>Verdict:</b> worth watching if you run three or more coding agents at once; otherwise skip.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 54 times before, and &#39;multi-agent&#39; 16 times. New here: a specific tool, Worktrunk, for running parallel coding agents in Git worktrees (the presenter says Better Stack already did a video on Claude Code&#39;s built-in worktrees).</div><div class="sh">The problem</div><ul><li><strong>Agents stepping on each other:</strong> Two agents in one folder break each other&#39;s tests; a Git worktree gives each its own checkout on its own branch, but plain Git needs the branch name typed three times to create one and three commands to clean up. Claude Code&#39;s native worktrees fix creation but have no merge command and no status view (<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=30s" target="_blank" rel="noopener">0:30</a>–<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=86s" target="_blank" rel="noopener">1:26</a>)</li></ul><div class="sh">Worktrunk in use</div><ul><li><strong>One command per agent:</strong> `wt switch` creates a worktree and starts Claude on a feature in one line; he runs three agents on three branches in three folders (<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=86s" target="_blank" rel="noopener">1:26</a>–<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=143s" target="_blank" rel="noopener">2:23</a>)</li><li><strong>`wt list`:</strong> Shows every worktree, its branch, how far ahead of main it is and diff size, with a robot icon for a working agent and a speech bubble for one waiting on you (<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=143s" target="_blank" rel="noopener">2:23</a>–<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=178s" target="_blank" rel="noopener">2:58</a>)</li><li><strong>`wt merge`:</strong> Commits, squashes, rebases onto main, fast-forwards and deletes the worktree, six Git commands in one (<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=178s" target="_blank" rel="noopener">2:58</a>–<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li><li><strong>Integrations:</strong> A Rust CLI (MIT or Apache) that installs a small shell function so it can change directory; it hooks into Claude Code&#39;s own worktree creation and has plugins for six agent CLIs including Codex, OpenCode and Gemini CLI (<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=186s" target="_blank" rel="noopener">3:06</a>–<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=271s" target="_blank" rel="noopener">4:31</a>)</li></ul><div class="sh">Speed tricks and limits</div><ul><li><strong>Copy-on-write for ignored files:</strong> A step command clones node_modules, build caches and env files with copy-on-write, so a 14 GB Rust build folder copies in about 20 seconds using almost no space instead of 2 minutes and 14 GB, and a first build drops from about 68 seconds to 3–4 (the author&#39;s numbers). A hash-port filter gives each worktree its own dev-server port (<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=271s" target="_blank" rel="noopener">4:31</a>–<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=331s" target="_blank" rel="noopener">5:31</a>)</li><li><strong>Downsides:</strong> It&#39;s pre-1.0 with &quot;breaking&quot; appearing 80+ times in the changelog, merge conflicts still land on you, copy-on-write only works on filesystems like APFS (plain ext4 gets full copies), and project hooks run shell commands, so read what you approve. With only one agent, native worktrees are enough (<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=331s" target="_blank" rel="noopener">5:31</a>–<a href="https://www.youtube.com/watch?v=mNo24Omj8X4&amp;t=434s" target="_blank" rel="noopener">7:14</a>)</li></ul></div></article></div>',1))])}const q=u(I,[["render",W]]);export{Q as __pageData,q as default};
